import sys
from rich.traceback import Traceback
from rich.console import Console

def test_nested_exception_groups():
    try:
        # Create deeply nested ExceptionGroups
        exc = Exception("Root")
        for i in range(1000):
            exc = ExceptionGroup(f"Group {i}", [exc])
        raise exc
    except ExceptionGroup as eg:
        try:
            console = Console(file_open=False)
            # This should not raise RecursionError
            Traceback.extract(type(eg), eg, eg.__traceback__)
            print("Successfully extracted deep ExceptionGroup")
        except RecursionError:
            print("FAILED: RecursionError caught")
            sys.exit(1)
        except Exception as e:
            print(f"FAILED: Other exception {e}")
            sys.exit(1)

if __name__ == "__main__":
    test_nested_exception_groups()

